export const HARDEOL_DATA={name:"Hardeol",title:"Mount Hardeol",elevation:"7,151 m",elevationFt:"23,461 ft",prominence:"1,300 m (4,300 ft)",state:"Uttarakhand",district:"Pithoragarh",range:"Kumaon Himalayas",alternateNames:["Trishuli South","Temple of God"],rankWorld:"46th Highest Peak in the World",coordinates:"30°33′36″N 80°00′36″E",firstAscent:"May 31, 1978",firstAscentTeam:"Indo-Tibet Border Police (ITBP), led by S. P. Mulasi",secondAscent:"September 24, 1991",secondAscentTeam:"Border Security Force (BSF) expedition — five summiters",overview:{geography:"Mount Hardeol (Sanskrit: 'Temple of God', also 'Trishuli South') is the highest peak on the northern side of the ring of peaks that guard the Nanda Devi Sanctuary, perched at its northeast corner. It lies at the northern end of the Milam valley in the Pithoragarh district of Uttarakhand, just south of Trishuli and north of Rishi Pahar, on a north–south trending ridge that leads toward Nanda Devi East.",significance:"After a reconnaissance in 1939 and serious attempts starting in 1967, Hardeol was first summitted on 31 May 1978 by an Indo-Tibetan Border Police expedition led by S. P. Mulasi, climbing the ridge connecting the peak to Trishuli. Only one further ascent is recorded in the Himalayan Index — a Border Security Force expedition that placed five climbers on the summit on 24 September 1991.",climbingCharacter:"Hardeol is a formidable, technical high-altitude objective requiring Indian Mountaineering Foundation permits, glacier travel through the Ikualari glacier and Hardeol icefall, expert ice-craft, crevasse-rescue skills, and rigorous acclimatisation. The best approach is from the east, via the Ikualari glacier into the Trishuli valley. Locals of the Johar valley call it Hardoli and worship it as their presiding mountain deity."},facts:[{title:"Northern Rim Crown Jewel",value:"7,151 m",description:"Hardeol is the highest peak on the northern side of the ring of peaks guarding the Nanda Devi Sanctuary, standing proud at the northeast corner of this sacred ring.",icon:"🏔️"},{title:"1978 First Ascent",value:"ITBP Expedition",description:"Summitted on 31 May 1978 by the Indo-Tibet Border Police, led by S. P. Mulasi via the Trishuli connecting ridge — its first and most celebrated climb.",icon:"📜"},{title:"Sacred Sentinel",value:"Temple of God",description:"Also known as 'Trishuli South', Hardeol means 'Temple of God' and is reverently called Hardoli by locals who worship it as their mountain deity.",icon:"🙏"},{title:"Only Two Ascents",value:"BSF 1991",description:"Just two summit successes appear in the Himalayan Index — ITBP in 1978 and BSF on 24 Sep 1991 (five climbers), thirteen years apart.",icon:"⛷️"},{title:"Kumaon Giant",value:"Pithoragarh",description:"Perched on the Uttarakhand–Tibet border at the head of the Milam valley, Hardeol is a landmark of the Kumaon Himalayas.",icon:"🗻"},{title:"Trishuli Ridge Link",value:"Nanda Devi East",description:"A north–south ridge connects Hardeol to Trishuli (north) and continues toward Nanda Devi East — a defining line of the sanctuary's rim.",icon:"⛰️"}],routes:[{step:1,stage:"Munsiyari – Trek Start",altitude:"2,290 m",description:"Hardeol's nearest motorable road is Munsiyari, the gateway town to the Milam valley. Trekkers and porters begin here, entering the remote Kumaon Himalaya and descending toward the river Gori.",keyHighlight:"Last supply and permit checkpoint before the high-altitude approach."},{step:2,stage:"Milam Valley → Base Camp",altitude:"~4,700 m",description:"From Milam village, the route follows the Milam glacier moraine. Base Camp is established on the moraine at the confluence where the glacier branches off toward the foot of the Hardeol icefall.",keyHighlight:"C1 sat on the moraine running through the middle of the Milam glacier beneath the Hardeol icefall."},{step:3,stage:"Ikualari Glacier Icefall (C2)",altitude:"5,180 m",description:"The ascent scales a steep ice-wall on the Ikualari glacier. Ropes are fixed and the team climbs up onto a raised snow-bump to establish Camp 2.",keyHighlight:"Glacier travel demanding rope teams, crampons and fixed-rope negotiation through crevassed terrain."},{step:4,stage:"Under Trishuli (C4)",altitude:"~5,880 m",description:"From C2 the route crosses crevassed snow slopes and an imposing 80 m snow wall, dropping into a re-entrant beneath the looming Trishuli ridge to camp at roughly 5,880 m.",keyHighlight:"Camp 4 sat under the shadow of Trishuli after a harrowing snow-wall and crevasse crossing."},{step:5,stage:"Tirsuli Ridge High Camp",altitude:"~6,250 – 6,550 m",description:"The party traverses onto the Tirsuli ridge itself, breaking through its virgin rim to establish higher camps (C6/C7) from where the full scale of the icefield is visible.",keyHighlight:"Only the ridge between Hardeol and Trishuli offers a safe line — the flanks are sheer and avalanche-prone."},{step:6,stage:"Summit Push",altitude:"7,151 m",description:"From the high ridge camp, climbers tackle Hardeol's northwestern ridge over a final bump and corniced sections to stand on the snow-capped summit — the 'Temple of God'.",keyHighlight:"360-degree panorama of the Nanda Devi Sanctuary ring, Trishuli, and the Tibetan plateau beyond."}],gallery:[{title:"Hardeol Above the Milam Glacier",caption:"The towering northwestern ridge of Hardeol rising above the Ikualari glacier approach.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Kangchenjunga_PangPema.JPG/960px-Kangchenjunga_PangPema.JPG"},{title:"Trishuli and Hardeol Ridge",caption:"The sharp north–south ridge linking Trishuli to Hardeol, the only viable climbing line.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Time_lapse_shot_of_Trishul_peak.jpg/960px-Time_lapse_shot_of_Trishul_peak.jpg"},{title:"Milam Valley Approach",caption:"The rugged Milam valley corridor, the classic approach into the Kumaon Himalayas.",image:"https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80"}],funFacts:[{title:"Temple of the Gods",description:"Hardeol literally means 'Temple of God'. Locals of the Johar valley call it Hardoli and worship it as their presiding mountain deity that guards their land."},{title:"Formerly nameless",description:"For decades before recognition, cartographers had no distinct name for the peak — it was recorded merely as the south peak of Trishuli."},{title:"A giant resisted",description:"Despite a 1939 reconnaissance, serious attempts began only in 1967. The peak eluded climbers for over half a century until the 1978 breakthrough."},{title:"Only two ascents",description:"Just two summit successes appear in the Himalayan Index: the ITBP in 1978 and the BSF in 1991 — thirteen years apart, and nothing since."},{title:"Captured before climbed",description:"One of the earliest known photographs of Hardeol alongside Trishuli was taken by Kurt Boeck as early as 1890, long before any climber set foot."},{title:"Sanctuary sentinel",description:"Hardeol crowns the northeast corner of the ring of peaks that guard the Nanda Devi Sanctuary, making it the highest sentinel there on the northern rim."}],nearbyAttractions:[{name:"Milam Village",distance:"Approach base",description:"The last permanent settlement in the scenic Milam valley, nestled beneath the Hardeol icefall — the cultural and logistical heart of the approach."},{name:"Munsiyari",distance:"Nearest motorable road",description:"A high-altitude hill station famed for the Paleolithic Museum, ancient Bhotiya trade routes, and panoramic views of the Panchachuli peaks."},{name:"Nanda Devi National Park",distance:"Within the sanctuary ring",description:"A UNESCO World Heritage Site surrounding the Nanda Devi Sanctuary, known for its pristine high-altitude ecosystem."},{name:"Bugyals of Munsiyari",distance:"20 km",description:"Alpine meadows that burst into wildflower colour in summer, offering iconic views of Hardeol and Trishuli looming overhead."},{name:"Dharchula",distance:"60 km",description:"A border town at the confluence of the Kali and Gori rivers, the gateway to the Milam and Kuthiya (Darma) valleys."}]};export function renderHardeolFacts(e,t){t&&Array.isArray(e)&&(t.innerHTML=e.map(e=>`\n        <article class="fact-card">\n            <div class="fact-icon">${e.icon}</div>\n            <div class="fact-value">${e.value}</div>\n            <h3 class="fact-title">${e.title}</h3>\n            <p class="fact-desc">${e.description}</p>\n        </article>\n    `).join(""))}export function renderHardeolRoutes(e,t){t&&Array.isArray(e)&&(t.innerHTML=e.map((e,t)=>`\n        <div class="route-step-card ${0===t?"active":""}" data-step="${e.step}">\n            <div class="step-badge">Step ${e.step}</div>\n            <h3 class="step-stage">${e.stage}</h3>\n            <div class="step-altitude">📍 Altitude: ${e.altitude}</div>\n            <p class="step-desc">${e.description}</p>\n            <div class="step-highlight">✨ <strong>Highlight:</strong> ${e.keyHighlight}</div>\n        </div>\n    `).join(""))}export function renderHardeolGallery(e,t){t&&Array.isArray(e)&&(t.innerHTML=e.map(e=>`\n        <figure class="gallery-card">\n            <img \n                src="${e.image}" \n                alt="${e.title}" \n                class="gallery-img" \n                loading="lazy"\n                onerror="this.onerror=null; this.src='data:image/svg+xml;utf8,<svg xmlns=\\'http://www.w3.org/2000/svg\\' width=\\'400\\' height=\\'250\\' viewBox=\\'0 0 100 100\\'><rect width=\\'100%\\' height=\\'100%\\' fill=\\'%231e293b\\'/><text x=\\'50%\\' y=\\'55%\\' fill=\\'%2338bdf8\\' font-size=\\'24\\' text-anchor=\\'middle\\'>🏔️</text></svg>';"\n            />\n            <figcaption class="gallery-caption">\n                <h4>${e.title}</h4>\n                <p>${e.caption}</p>\n            </figcaption>\n        </figure>\n    `).join(""))}export function renderHardeolFunFacts(e,t){t&&Array.isArray(e)&&(t.innerHTML=e.map((e,t)=>`\n        <article class="funfact-card">\n            <div class="funfact-icon">💡</div>\n            <div class="funfact-body">\n                <h3 class="funfact-title">${e.title}</h3>\n                <p class="funfact-desc">${e.description}</p>\n            </div>\n        </article>\n    `).join(""))}export function renderHardeolAttractions(e,t){t&&Array.isArray(e)&&(t.innerHTML=e.map(e=>`\n        <article class="attraction-card">\n            <div class="attr-header">\n                <span class="attr-icon">🏔️</span>\n                <div>\n                    <h3 class="attr-name">${e.name}</h3>\n                    <span class="attr-dist">📍 ${e.distance}</span>\n                </div>\n            </div>\n            <p class="attr-desc">${e.description}</p>\n        </article>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("facts-grid"),t=document.getElementById("routes-grid"),a=document.getElementById("gallery-grid"),i=document.getElementById("funfacts-grid"),n=document.getElementById("attractions-grid");e&&renderHardeolFacts(HARDEOL_DATA.facts,e),t&&renderHardeolRoutes(HARDEOL_DATA.routes,t),a&&renderHardeolGallery(HARDEOL_DATA.gallery,a),i&&renderHardeolFunFacts(HARDEOL_DATA.funFacts,i),n&&renderHardeolAttractions(HARDEOL_DATA.nearbyAttractions,n)});